const keywords = [
  "n8n workflow",
  "n8n automation",
  "n8n AI agent",
  "n8n Gmail automation",
  "n8n WhatsApp automation",
  "n8n Google Sheets automation",
  "n8n Slack automation",
  "n8n CRM automation"
];

return keywords.map(keyword => ({
  json: {
    keyword
  }
}));

const inputs = $input.all();

const uniqueVideos = new Map();

for (const input of inputs) {
  const results = input.json.items || [];

  for (const video of results) {
    const videoId = video.id?.videoId;

    if (!videoId) continue;

    if (!uniqueVideos.has(videoId)) {
      uniqueVideos.set(videoId, video);
    }
  }
}

return Array.from(uniqueVideos.values()).map(video => ({
  json: {
    video_id: video.id.videoId,
    title: video.snippet?.title || null,
    description: video.snippet?.description || null,
    channel_id: video.snippet?.channelId || null,
    channel_title: video.snippet?.channelTitle || null,
    published_at: video.snippet?.publishedAt || null,
    thumbnail:
      video.snippet?.thumbnails?.high?.url ||
      video.snippet?.thumbnails?.default?.url ||
      null,
    source_platform: "youtube"
  }
}));

const items = $input.all();

const videoIds = items
  .map(item => item.json.video_id)
  .filter(Boolean);

const batches = [];

for (let i = 0; i < videoIds.length; i += 50) {
  const batch = videoIds.slice(i, i + 50);

  batches.push({
    json: {
      videoIds: batch
    }
  });
}

return batches;

const statisticsInput = $input.all();
const searchItems = $('YT Search').all();

// 1. Build lookup map from YT Search node
const searchMap = new Map();
for (const item of searchItems) {
  // Handles both raw API output (items array) and flattened outputs
  const rawResults = item.json.items || item.json;
  const list = Array.isArray(rawResults) ? rawResults : [rawResults];

  for (const video of list) {
    // Extracts videoId whether nested (id.videoId) or flat (id)
    const videoId = typeof video.id === 'object' ? video.id?.videoId : video.id;
    if (videoId) {
      searchMap.set(videoId, video);
    }
  }
}

// 2. Process statistics items
const output = [];
for (const item of statisticsInput) {
  // Extracts items array from YT - Statistics response
  const statsList = item.json.items || (Array.isArray(item.json) ? item.json : [item.json]);

  for (const videoStats of statsList) {
    const videoId = typeof videoStats.id === 'object' ? videoStats.id?.videoId : videoStats.id;
    if (!videoId) continue;

    const searchData = searchMap.get(videoId);
    const stats = videoStats.statistics || {};

    output.push({
      json: {
        video_id: videoId,
        title: searchData?.snippet?.title || searchData?.title || null,
        description: searchData?.snippet?.description || searchData?.description || null,
        channel_id: searchData?.snippet?.channelId || searchData?.channelId || null,
        channel_title: searchData?.snippet?.channelTitle || searchData?.channelTitle || null,
        published_at: searchData?.snippet?.publishedAt || searchData?.publishedAt || null,
        thumbnail: searchData?.snippet?.thumbnails?.high?.url || searchData?.snippet?.thumbnails?.default?.url || searchData?.thumbnail || null,
        views: Number(stats.viewCount || 0),
        likes: Number(stats.likeCount || 0),
        comments: Number(stats.commentCount || 0),
        source_platform: "youtube",
        source_url: `https://www.youtube.com/watch?v=${videoId}`,
        collected_at: new Date().toISOString()
      }
    });
  }
}

return output;

const items = $input.all();

const validItems = [];

for (const item of items) {
  const data = item.json;

  const title = String(data.title || "").toLowerCase();
  const description = String(data.description || "").toLowerCase();

  const text = `${title} ${description}`;

  // Relevance check
  const isN8nRelated = text.includes("n8n");

  const isWorkflowRelated =
    text.includes("workflow") ||
    text.includes("automation");

  // Numeric validation
  const views = Number(data.views);
  const likes = Number(data.likes);
  const comments = Number(data.comments);

  const validMetrics =
    Number.isFinite(views) &&
    Number.isFinite(likes) &&
    Number.isFinite(comments) &&
    views >= 0 &&
    likes >= 0 &&
    comments >= 0;

  if (!isN8nRelated || !isWorkflowRelated || !validMetrics) {
    continue;
  }

  // Engagement metrics
  const likeToViewRatio =
    views > 0 ? likes / views : 0;

  const commentToViewRatio =
    views > 0 ? comments / views : 0;

  validItems.push({
    json: {
      ...data,

      like_to_view_ratio: likeToViewRatio,
      comment_to_view_ratio: commentToViewRatio,

      validation_status: "valid"
    }
  });
}

return validItems;

const items = $input.all();

if (items.length === 0) {
  return [];
}

// Find maximum values for normalization
const maxViews = Math.max(
  ...items.map(item => Math.log1p(Number(item.json.views || 0)))
);

const maxLikeRate = Math.max(
  ...items.map(item => Number(item.json.like_to_view_ratio || 0))
);

const maxCommentRate = Math.max(
  ...items.map(item => Number(item.json.comment_to_view_ratio || 0))
);

return items.map(item => {
  const data = item.json;

  const views = Number(data.views || 0);
  const likeRate = Number(data.like_to_view_ratio || 0);
  const commentRate = Number(data.comment_to_view_ratio || 0);

  // Log scale prevents very high-view videos from dominating everything
  const viewsScore =
    maxViews > 0
      ? (Math.log1p(views) / maxViews) * 100
      : 0;

  const likeRateScore =
    maxLikeRate > 0
      ? (likeRate / maxLikeRate) * 100
      : 0;

  const commentRateScore =
    maxCommentRate > 0
      ? (commentRate / maxCommentRate) * 100
      : 0;

  // Documented weights
  const popularityScore =
    (viewsScore * 0.50) +
    (likeRateScore * 0.30) +
    (commentRateScore * 0.20);

  return {
    json: {
      ...data,

      views_score: Number(viewsScore.toFixed(2)),
      like_rate_score: Number(likeRateScore.toFixed(2)),
      comment_rate_score: Number(commentRateScore.toFixed(2)),

      popularity_score: Number(popularityScore.toFixed(2)),

      scoring_method:
        "50% log-normalized views + 30% like/view ratio + 20% comment/view ratio"
    }
  };
});

const items = $input.all();

return items
  .sort(
    (a, b) =>
      Number(b.json.popularity_score || 0) -
      Number(a.json.popularity_score || 0)
  )
  .map((item, index) => ({
    json: {
      rank: index + 1,
      ...item.json,

      country_segment: "unknown",
      data_type: "youtube_workflow"
    }
  }));

const items = $input.all()
return [
  {
    json: {
      source: "youtube",
      records: items.map(item => item.json)
    }
  }
];

const items = $input.all();

const validItems = [];

for (const item of items) {
  const data = item.json;

  const title = String(data.title || "").toLowerCase();
  const description = String(data.description || "").toLowerCase();

  const text = `${title} ${description}`;

  // Must be related to n8n
  const isN8nRelated = text.includes("n8n");

  // Should discuss workflows or automation
  const isWorkflowRelated =
    text.includes("workflow") ||
    text.includes("automation");

  // Basic metric validation
  const hasValidViews =
    Number.isFinite(Number(data.views)) &&
    Number(data.views) >= 0;

  const hasValidLikes =
    Number.isFinite(Number(data.likes)) &&
    Number(data.likes) >= 0;

  const hasValidComments =
    Number.isFinite(Number(data.comments)) &&
    Number(data.comments) >= 0;

  if (
    isN8nRelated &&
    isWorkflowRelated &&
    hasValidViews &&
    hasValidLikes &&
    hasValidComments
  ) {
    validItems.push({
      json: data
    });
  }
}

return validItems;

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const views = Number(data.views || 0);
  const likes = Number(data.likes || 0);
  const comments = Number(data.comments || 0);

  const likeToViewRatio =
    views > 0 ? likes / views : 0;

  const commentToViewRatio =
    views > 0 ? comments / views : 0;

  return {
    json: {
      ...data,

      like_to_view_ratio: likeToViewRatio,
      comment_to_view_ratio: commentToViewRatio
    }
  };
});

const items = $input.all();
const seen = new Set();
const uniqueItems = [];

for (const item of items) {
  const data = item.json;

  const key = `${data.source_platform}:${data.video_id}`;

  if (!seen.has(key)) {
    seen.add(key);
    uniqueItems.push(item);
  }
}

return uniqueItems;
